//! Our `win32u.dll` (ADR 0128, Decision 2): the stubs of Poly's own win32k
//! system calls (`PolyUser*`, `PolyGdi*`), generated by `build.rs` from
//! `poly_win32k::services::WIN32K_SERVICES` and exported by name for our
//! `user32.dll` and `gdi32.dll`. Windows' own `NtUser*` / `NtGdi*` names
//! are not exported: their arguments are undocumented, so a program that
//! calls one directly fails to bind instead of reaching a Poly service with
//! misread arguments. A Windows name joins only as an adapter, once a spec
//! sheet documents it.

#![no_std]

use poly_win32_rt as _;

core::arch::global_asm!(include_str!(env!("WIN32U_SYSCALLS")));

/// The entry point (`DllMain`): nothing to set up.
#[unsafe(no_mangle)]
pub extern "system" fn win32u_main(_module: *mut u8, _reason: u32, _reserved: *mut u8) -> i32 {
    1
}
